script:
(function () {
  'use strict';
  // Payment calculator: fixed-rate loan, monthly payments, rate is an APR compounded monthly (i = r/12).
  //   Payment for a term of n months: PMT = L * i / (1 - (1 + i)^-n); PMT = L / n at 0%.
  //   Term for a fixed payment P: simulate month by month (n = -ln(1 - L*i/P) / ln(1 + i) in closed
  //   form); the last payment is whatever clears the balance. P must exceed the first month's interest L*i.
  // Verified in Node (scratchpad w3loans/tests): $200,000 at 6% for 15 years = $1,687.71/mo, total
  //   interest $103,788.46 (closed form; matches a published calculator's default result); $25,000 at 7%
  //   for 5 years = $495.03/mo; $12,000 at 0% for 24 months = $500.00; $200,000 at 6% paying $2,000/mo
  //   takes 139 payments (11 years 7 months, final payment $1,951.56), matching the closed form n = 138.98; a payment that does
  //   not cover the interest, blank, negative and 0-term input show an error, never NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var pct = new Intl.NumberFormat('en-US', { style: 'percent', minimumFractionDigits: 1, maximumFractionDigits: 1 });
  var MAX_MONTHS = 1200;
  var last = null;

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function mode() {
    var r = document.querySelector('input[name="pmMode"]:checked');
    return r ? r.value : 'payment';
  }

  function payment(principal, i, n) {
    if (n <= 0 || principal <= 0) return 0;
    if (i === 0) return principal / n;
    return principal * i / (1 - Math.pow(1 + i, -n));
  }

  // Pays `pay` each month until the balance is gone (or maxN payments). Returns the rows.
  function simulate(loan, i, pay, maxN) {
    var bal = loan, rows = [], totalInterest = 0, totalPaid = 0;
    for (var k = 1; k <= maxN && bal > 0.005; k++) {
      var interest = bal * i;
      var amount = Math.min(pay, bal + interest);
      bal = bal + interest - amount;
      if (bal < 0.005) bal = 0;
      totalInterest += interest;
      totalPaid += amount;
      rows.push({ n: k, amount: amount, interest: interest, principal: amount - interest, balance: bal });
    }
    return { rows: rows, totalInterest: totalInterest, totalPaid: totalPaid, balance: bal };
  }

  function duration(months) {
    months = Math.round(months);
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function cell(tr, text) { var td = document.createElement('td'); td.textContent = text; tr.appendChild(td); }

  function headRow(id, labels) {
    var head = el(id);
    head.textContent = '';
    var tr = document.createElement('tr');
    labels.forEach(function (t) { var th = document.createElement('th'); th.scope = 'col'; th.textContent = t; tr.appendChild(th); });
    head.appendChild(tr);
  }

  function clearResults() {
    ['pmMain', 'pmInterest', 'pmTotal', 'pmCount', 'pmFinal', 'pmShare'].forEach(function (id) { setText(id, '–'); });
    el('pmCompare').textContent = '';
    el('pmSchedule').textContent = '';
    last = null;
  }

  function renderSchedule() {
    var body = el('pmSchedule');
    body.textContent = '';
    if (!last) return;
    if (el('pmView').value === 'period') {
      headRow('pmScheduleHead', ['Payment', 'Amount', 'Principal', 'Interest', 'Balance']);
      last.rows.forEach(function (row) {
        var tr = document.createElement('tr');
        cell(tr, String(row.n)); cell(tr, money.format(row.amount)); cell(tr, money.format(row.principal));
        cell(tr, money.format(row.interest)); cell(tr, money.format(row.balance));
        body.appendChild(tr);
      });
    } else {
      headRow('pmScheduleHead', ['Year', 'Principal', 'Interest', 'Ending balance']);
      var p = 0, intr = 0;
      last.rows.forEach(function (row, idx) {
        p += row.principal; intr += row.interest;
        if (row.n % 12 === 0 || idx === last.rows.length - 1) {
          var tr = document.createElement('tr');
          cell(tr, String(Math.ceil(row.n / 12))); cell(tr, money.format(p)); cell(tr, money.format(intr));
          cell(tr, money.format(row.balance));
          body.appendChild(tr);
          p = 0; intr = 0;
        }
      });
    }
  }

  function renderCompare(amount, i, m, termMonths, pay) {
    var body = el('pmCompare');
    body.textContent = '';
    if (m === 'payment') {
      setText('pmCompareHeading', 'Payment at other terms');
      headRow('pmCompareHead', ['Term', 'Monthly payment', 'Total interest']);
      var terms = [36, 60, 84, 120, 180, 240, 360];
      if (terms.indexOf(termMonths) === -1) terms.push(termMonths);
      terms.sort(function (a, b) { return a - b; });
      terms.forEach(function (t) {
        var pmt = payment(amount, i, t), tr = document.createElement('tr');
        cell(tr, duration(t) + (t === termMonths ? ' (yours)' : ''));
        cell(tr, money.format(pmt));
        cell(tr, money.format(Math.max(0, pmt * t - amount)));
        body.appendChild(tr);
      });
    } else {
      setText('pmCompareHeading', 'Payoff time at other payments');
      headRow('pmCompareHead', ['Monthly payment', 'Time to pay off', 'Total interest']);
      [1, 1.1, 1.25, 1.5, 2].forEach(function (f) {
        var p = f === 1 ? pay : Math.ceil(pay * f), s = simulate(amount, i, p, MAX_MONTHS), tr = document.createElement('tr');
        cell(tr, money.format(p) + (f === 1 ? ' (yours)' : ''));
        cell(tr, s.balance > 0 ? 'Over 100 years' : duration(s.rows.length));
        cell(tr, money.format(s.totalInterest));
        body.appendChild(tr);
      });
    }
  }

  function update() {
    var m = mode();
    el('pmTermFields').hidden = m !== 'payment';
    el('pmPayField').hidden = m !== 'term';
    var amount = read('pmAmount'), rate = read('pmRate'), years = read('pmYears', true), months = read('pmMonths', true),
        pay = read('pmPay'), msg = '';
    var termMonths = years * 12 + months;
    if (isNaN(amount) || amount <= 0) msg = 'Enter a loan amount greater than $0.';
    else if (isNaN(rate) || rate < 0 || rate > 100) msg = 'Enter an interest rate from 0% to 100%.';
    else if (m === 'payment') {
      if (isNaN(years) || isNaN(months) || years < 0 || months < 0 || years % 1 !== 0 || months % 1 !== 0 || years > 50 || months > 11)
        msg = 'Enter the term as whole years (0 to 50) and months (0 to 11).';
      else if (termMonths < 1) msg = 'Enter a loan term of at least one month.';
    } else if (isNaN(pay) || pay <= 0) msg = 'Enter a monthly payment greater than $0.';
    var i = isNaN(rate) ? 0 : rate / 100 / 12;
    if (!msg && m === 'term' && pay <= amount * i + 0.005)
      msg = 'That payment does not cover the first month’s interest of ' + money.format(amount * i) +
            ', so the loan would never be repaid. Enter a larger payment.';
    var r = null;
    if (!msg) {
      r = m === 'payment' ? simulate(amount, i, payment(amount, i, termMonths), termMonths + 1) : simulate(amount, i, pay, MAX_MONTHS);
      if (m === 'term' && r.balance > 0) msg = 'At that payment the loan would take more than 100 years to repay. Enter a larger payment.';
    }
    var error = el('pmError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var n = r.rows.length, finalPay = r.rows[n - 1].amount;
    if (m === 'payment') {
      setText('pmMainLabel', 'Monthly payment');
      setText('pmMain', money.format(r.rows[0].amount));
      setText('pmSummary', 'Pay ' + money.format(r.rows[0].amount) + ' a month for ' + duration(termMonths) + ' to repay the loan.');
    } else {
      setText('pmMainLabel', 'Time to pay off');
      setText('pmMain', duration(n));
      setText('pmSummary', 'Paying ' + money.format(pay) + ' a month clears the loan in ' + n + (n === 1 ? ' payment.' : ' payments.'));
    }
    setText('pmInterest', money.format(r.totalInterest));
    setText('pmTotal', money.format(r.totalPaid));
    setText('pmCount', String(n));
    setText('pmFinal', money.format(finalPay));
    setText('pmShare', pct.format(r.totalInterest / amount));
    last = { rows: r.rows };
    renderCompare(amount, i, m, termMonths, pay);
    renderSchedule();
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('pmForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    el('pmView').addEventListener('change', renderSchedule);
    update();
  });
})();
